"""Data structures shared by the three forecasting methods (Sec. 3)."""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional

import numpy as np

from ..data.types import Dataset, Example


@dataclass
class CandidateVocab:
    """A pruned output vocabulary.

    Sec. 3.2: "In practice, we only cache top k = 100 largest logits for each
    token in y_j."  We collect the top-k ids of every upstream example (plus the
    gold token ids) into one candidate set and store all logits restricted to it.
    """

    vocab_ids: np.ndarray            # [C] original vocabulary ids
    topk: int = 100
    max_size: int = 512

    def __len__(self) -> int:
        return int(self.vocab_ids.shape[0])

    def reduce(self, logits: np.ndarray) -> np.ndarray:
        return logits[:, self.vocab_ids]

    def to_dict(self) -> Dict:
        return {"vocab_ids": self.vocab_ids.tolist(), "topk": self.topk, "max_size": self.max_size}

    @classmethod
    def from_dict(cls, obj: Dict) -> "CandidateVocab":
        return cls(np.asarray(obj["vocab_ids"], dtype=np.int64), int(obj["topk"]), int(obj["max_size"]))


@dataclass
class UpstreamExampleCache:
    """Everything that can be pre-computed for one upstream example x_j."""

    example: Example
    reduced_logits: np.ndarray        # [T_j, C] pre-softmax logits of the gold tokens of f_0
    gold_ids: np.ndarray              # [T_j] gold token ids
    mask: np.ndarray                  # [T_j] bool, True for non-padding positions
    decoder_reps: np.ndarray          # [T_j, H] frozen decoder representations (fixed logit kernel)
    pooled_rep: np.ndarray            # [H] mean-pooled representation of <x_j, y_j>
    correct: bool                     # f_0(x_j) == y_j  (i.e. x_j is in D_hat_PT)


@dataclass
class UpstreamCache:
    """Cached logits / representations of ``D_PT`` (all methods reuse these)."""

    examples: Dataset
    vocab: CandidateVocab
    items: List[UpstreamExampleCache] = field(default_factory=list)
    base_em: float = float("nan")

    def __len__(self) -> int:
        return len(self.items)

    @property
    def correct_mask(self) -> np.ndarray:
        return np.asarray([item.correct for item in self.items], dtype=bool)

    def subset(self, indices) -> "UpstreamCache":
        return UpstreamCache(
            examples=[self.examples[i] for i in indices],
            vocab=self.vocab,
            items=[self.items[i] for i in indices],
            base_em=self.base_em,
        )

    def pooled_matrix(self) -> np.ndarray:
        return np.stack([item.pooled_rep for item in self.items], axis=0)


@dataclass
class OnlineArtifact:
    """What one online learning example contributes to forecasting."""

    example: Example
    delta_logits: np.ndarray          # [T_i, C] f_i(x_i) - f_0(x_i), reduced to the candidate vocab
    gold_ids: np.ndarray              # [T_i] gold token ids of y_i
    mask: np.ndarray                  # [T_i] bool
    labels: Optional[np.ndarray] = None      # [N_PT] ground truth z_ij (None for test-time input)
    edit_success: bool = False               # f_i(x_i) == y_i after the update
    n_steps: int = 0

    @property
    def key(self) -> str:
        return self.example.key

"""Sec. 3.1 -- Frequency-threshold based forecasting.

    g(<x_i, y_i>, <x_j, y_j>) = 1[ |{i in D_R^Train : z_ij = 1}| >= gamma ]

``gamma`` is tuned to maximise the F1 on ``D_R^Train``.  The method ignores the
interaction between the two examples and only uses how often the upstream
example was forgotten.  Note the paper's ``J = |D_PT|`` is a typo: the count runs
over the online learned examples of ``D_R^Train`` (see addendum for Sec. 3.1).
"""
from __future__ import annotations

from typing import Dict, Optional

import numpy as np

from ..evaluation.metrics import precision_recall_f1
from .base import BaseForecaster, ForecastContext


class ThresholdForecaster(BaseForecaster):
    name = "threshold"
    trainable = False

    def __init__(self, gamma: Optional[int] = None) -> None:
        self.gamma = gamma
        self.counts: Optional[np.ndarray] = None

    def fit(self, ctx: ForecastContext) -> "ThresholdForecaster":
        labels = ctx.train_labels                       # [n_online, n_upstream]
        self.counts = labels.sum(axis=0).astype(np.int64)
        if self.gamma is None:
            self.gamma = self._tune_gamma(labels, ctx)
        return self

    # ----------------------------------------------------------------------------------
    @staticmethod
    def _tune_gamma(labels: np.ndarray, ctx: ForecastContext) -> int:
        n_online = labels.shape[0]
        best_gamma, best_f1 = 1, -1.0
        for gamma in range(1, n_online + 1):
            pred = (labels.sum(axis=0)[None, :] >= gamma).astype(int)
            _, _, f1 = precision_recall_f1(labels.reshape(-1), pred.reshape(-1))
            if f1 > best_f1:
                best_gamma, best_f1 = gamma, f1
        return best_gamma

    def scores(self, artifact) -> np.ndarray:
        if self.counts is None:
            raise RuntimeError("call fit() first")
        return self.counts.astype(np.float64)

    def predict(self, artifact) -> np.ndarray:
        return (self.scores(artifact) >= float(self.gamma or 1)).astype(int)

    def to_dict(self) -> Dict:
        return {"name": self.name, "gamma": float(self.gamma or 1), "n_upstream": int(len(self.counts or []))}

"""Example selection for replay-based model refinement (Sec. 4.2 / Sec. 5.2).

Every variant replays the *same number* of upstream examples at the *same*
intervals; they only differ in how the examples are selected:

* RandomReplay   -- uniform sample from D_PT.
* ScoreReplay    -- the examples forecasted to be forgotten (threshold-, logit-
  or representation-based prediction).
* GTForgetReplay -- the ground-truth forgotten examples (upper bound; needs
  inference with the updated LM and is therefore infeasible in practice).

MIR (Aljundi et al., 2019a) and OCS (Yoon et al., 2022) are declared out of
scope by the addendum and are therefore not part of the default runs.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, List, Optional, Sequence

import numpy as np

from ..data.types import Example
from ..forecasting.types import OnlineArtifact, UpstreamCache
from ..models.tuning import ReplayBatch


@dataclass
class ReplayPool:
    """D_PT examples plus the base PTLM's cached logits, ready for replay."""

    cache: UpstreamCache
    max_target_len: int

    @property
    def examples(self) -> List[Example]:
        return list(self.cache.examples)

    def __len__(self) -> int:
        return len(self.cache.examples)

    def batch(self, indices: Sequence[int]) -> ReplayBatch:
        """Distillation targets of the selected replay examples.

        Logits are taken from the candidate vocabulary cached with D_PT (the same
        top-k reduced vocabulary that the forecasting models use), which keeps the
        memory of the replay buffer tractable.
        """
        items = [self.cache.items[i] for i in indices]
        logits = np.stack(
            [
                np.pad(
                    item.reduced_logits.astype(np.float32),
                    ((0, max(0, self.max_target_len - item.reduced_logits.shape[0])), (0, 0)),
                )[: self.max_target_len]
                for item in items
            ],
            axis=0,
        )
        return ReplayBatch(
            inputs=[item.example.input for item in items],
            targets=[item.example.target for item in items],
            logits=logits,
        )

    def candidate_vocab(self) -> np.ndarray:
        return self.cache.vocab.vocab_ids


class RandomReplay:
    """Baseline: replay a uniformly random mini-batch of D_PT."""

    name = "random"

    def __init__(self, seed: int = 0) -> None:
        self.rng = np.random.default_rng(seed)

    def select(self, k: int, pool: ReplayPool, **kwargs) -> List[int]:
        n = len(pool)
        k = min(k, n)
        return sorted(self.rng.choice(n, size=k, replace=False).tolist())


class ScoreReplay:
    """Replay the examples predicted to be forgotten by a forecasting model."""

    name = "score"

    def __init__(
        self,
        forecaster,
        artifact_lookup: Callable[[Example], Optional[OnlineArtifact]],
        seed: int = 0,
        fill_random: bool = True,
    ) -> None:
        self.forecaster = forecaster
        self.artifact_lookup = artifact_lookup
        self.rng = np.random.default_rng(seed)
        self.fill_random = fill_random

    def select(self, k: int, pool: ReplayPool, online_example: Optional[Example] = None, **kwargs) -> List[int]:
        artifact = self.artifact_lookup(online_example) if online_example is not None else None
        if artifact is None:
            return RandomReplay(seed=int(self.rng.integers(1 << 30))).select(k, pool)
        pred = np.asarray(self.forecaster.predict(artifact)).reshape(-1)
        positive = np.flatnonzero(pred == 1).tolist()
        if len(positive) >= k:
            chosen = self.rng.choice(positive, size=k, replace=False).tolist()
        elif self.fill_random:
            chosen = positive + list(self.rng.choice(len(pool), size=k - len(positive), replace=False).tolist())
        else:
            chosen = positive
        return sorted(dict.fromkeys(chosen))


class GTForgetReplay:
    """Upper bound: replay the ground-truth forgotten upstream examples."""

    name = "gt_forget"

    def __init__(self, label_lookup: Callable[[Example], Optional[np.ndarray]], seed: int = 0) -> None:
        self.label_lookup = label_lookup
        self.rng = np.random.default_rng(seed)

    def select(self, k: int, pool: ReplayPool, online_example: Optional[Example] = None, **kwargs) -> List[int]:
        labels = self.label_lookup(online_example) if online_example is not None else None
        if labels is None:
            return RandomReplay(seed=int(self.rng.integers(1 << 30))).select(k, pool)
        positive = np.flatnonzero(np.asarray(labels).reshape(-1) == 1).tolist()
        if len(positive) >= k:
            chosen = self.rng.choice(positive, size=k, replace=False).tolist()
        else:
            chosen = positive + list(self.rng.choice(len(pool), size=k - len(positive), replace=False).tolist())
        return sorted(dict.fromkeys(chosen))


def make_replay_callback(strategy, pool: ReplayPool, online_example: Example, batch_size: int):
    """Return the ``replay_pool(step) -> ReplayBatch`` callable expected by
    :func:`wwmf.models.tuning.fix_single_error`."""

    def _callback(step: int) -> ReplayBatch:
        indices = strategy.select(batch_size, pool, online_example=online_example)
        return pool.batch(indices)

    return _callback

"""Sec. 5.3 -- computational efficiency of the forecasting methods (Table 5).

Notation of the paper: ``N_PT`` upstream pretraining examples, ``T`` maximal
input/output length, ``H`` representation dimension, ``V`` vocabulary size and
``Fw(N)`` the cost of running inference with ``N`` examples.  Logits and
representations of ``D_PT`` are cached, so they are computed once and reused for
every online learning example.

Table 5:

    Method / Setup     Head                   Full FT
    Threshold          O(N_PT)                O(N_PT)
    Trainable Logit    O(N_PT T^2 (H + V))    O(N_PT T^2 (H + V))
    Representation     O(N_PT H)              O(N_PT H)
    Ground Truth       O(N_PT T H V)          O(Fw(N))

Appendix C additionally reports FLOP counts; ``estimate_flops`` implements the
same accounting in closed form (see the README for the mapping).
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Dict

COMPLEXITY_TABLE: Dict[str, Dict[str, str]] = {
    "Threshold": {"head": "O(N_PT)", "full_ft": "O(N_PT)"},
    "Trainable Logit": {"head": "O(N_PT * T^2 * (H + V))", "full_ft": "O(N_PT * T^2 * (H + V))"},
    "Representation": {"head": "O(N_PT * H)", "full_ft": "O(N_PT * H)"},
    "Ground Truth": {"head": "O(N_PT * T * H * V)", "full_ft": "O(Fw(N))"},
}


@dataclass
class FlopEstimate:
    """Closed-form FLOP estimate for retrieving forgotten examples from D_PT."""

    n_upstream: int
    T: int
    H: int
    V: int
    candidate_vocab: int

    def threshold(self) -> float:
        return float(self.n_upstream)

    def representation(self) -> float:
        return float(self.n_upstream * self.H)

    def trainable_logit(self) -> float:
        return float(self.n_upstream * self.T * self.T * (self.H + self.V))

    def ground_truth(self, forward_flops_per_example: float) -> float:
        """``Fw(N_PT)``: one full forward pass of the updated LM over D_PT."""
        return float(self.n_upstream * forward_flops_per_example)

    def to_dict(self, forward_flops_per_example: float) -> Dict[str, float]:
        return {
            "Threshold": self.threshold(),
            "Representation": self.representation(),
            "Trainable Logit": self.trainable_logit(),
            "Ground Truth": self.ground_truth(forward_flops_per_example),
        }


def estimate_flops(
    n_upstream: int = 3600,
    T: int = 32,
    H: int = 1024,
    V: int = 32128,
    forward_flops_per_example: float = 2 * 780e6 * 64,
) -> Dict[str, float]:
    """FLOP counts in the style of Appendix C.

    ``forward_flops_per_example`` defaults to a rough estimate of one forward pass
    of FLAN-T5_Large on a 64-token sequence (2 * parameters * tokens).
    """
    return FlopEstimate(n_upstream, T, H, V, V).to_dict(forward_flops_per_example)

